validate:
(result, args, expected) => {
  const tickets = args[0];
  if (!Array.isArray(result)) return "Return an array of airport codes.";
  if (result.length !== tickets.length + 1) return "Using all " + tickets.length + " tickets visits " + (tickets.length + 1) + " airports, but your itinerary has " + result.length + ".";
  if (result[0] !== "JFK") return "The trip must start at JFK, but yours starts at " + result[0] + ".";
  const left = new Map();
  for (const [a, b] of tickets) left.set(a + ">" + b, (left.get(a + ">" + b) || 0) + 1);
  for (let i = 0; i + 1 < result.length; i++) {
    const key = result[i] + ">" + result[i + 1];
    if (!left.get(key)) return "Step " + (i + 1) + " flies " + result[i] + " to " + result[i + 1] + ", but there is no unused ticket for that.";
    left.set(key, left.get(key) - 1);
  }
  for (let i = 0; i < result.length; i++) {
    if (result[i] !== expected[i]) return "This uses every ticket once, but it is not the lexicographically smallest trip: at stop " + (i + 1) + " you go to " + result[i] + ", while a valid trip goes to " + expected[i] + ".";
  }
  return true;
}
